# Reference persistence: rebuild the PyUser from the flat mirror and write
# it back (addUser when isNew, editUser otherwise). Roles and contacts are
# rebuilt wholesale; a staged event.password is applied via u.set and NEVER
# logged. Bare except on purpose (Java exceptions).
import sys
s = event.user
username = str(s.username)
SRC = 'default'
try:
	if bool(event.isNew):
		u = system.user.getNewUser(SRC, username)
	else:
		u = system.user.getUser(SRC, username)
	u.set('firstname', str(s.firstName))
	u.set('lastname', str(s.lastName))
	u.set('schedule', str(s.schedule))
	u.set('language', str(s.language))
	u.set('notes', str(s.notes))
	try:
		u.setRoles([str(r) for r in s.roles])
	except:
		for r in list(u.roles):
			u.removeRole(str(r))
		for r in s.roles:
			u.addRole(str(r))
	try:
		u.setContactInfo([])
	except:
		for c in list(u.contactInfo):
			u.removeContactInfo(str(c.contactType), str(c.value))
	for c in s.contactInfo:
		u.addContactInfo(str(c.contactType), str(c.value))
	adjs = []
	for a in s.scheduleAdjustments:
		adjs.append(system.user.createScheduleAdjustment(system.date.parse(str(a.start), 'yyyy-MM-dd HH:mm'), system.date.parse(str(a.end), 'yyyy-MM-dd HH:mm'), bool(a.available), str(a.note)))
	try:
		u.setScheduleAdjustments(adjs)
	except:
		for a in list(u.scheduleAdjustments):
			u.removeScheduleAdjustment(a)
		for a in adjs:
			u.addScheduleAdjustment(a)
	pw = None
	try:
		pw = event.password
	except:
		pw = None
	if pw:
		u.set('password', str(pw))
	if bool(event.isNew):
		resp = system.user.addUser(SRC, u)
	else:
		resp = system.user.editUser(SRC, u)
	errs = [str(x) for x in resp.getErrors()]
	if errs:
		self.view.custom.lastEvent = 'onUserSave ERRORS: ' + '; '.join(errs)
	else:
		self.view.custom.lastEvent = 'onUserSave persisted "' + username + '" (isNew=' + str(bool(event.isNew)) + (', password set' if pw else '') + ')'
except:
	self.view.custom.lastEvent = 'onUserSave FAILED: ' + str(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

import sys
username = str(event.username)
if username == 'admin':
	self.view.custom.lastEvent = 'onUserDelete REFUSED: the demo keeps the admin account'
else:
	try:
		resp = system.user.removeUser('default', username)
		errs = [str(x) for x in resp.getErrors()]
		if errs:
			self.view.custom.lastEvent = 'onUserDelete ERRORS: ' + '; '.join(errs)
		else:
			self.view.custom.lastEvent = 'onUserDelete removed "' + username + '"'
	except:
		self.view.custom.lastEvent = 'onUserDelete FAILED: ' + str(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

# Role-catalog persistence: add or rename (editRole keeps user assignments
# — the source stores role ids — but POLICIES reference roles by name).
import sys
name = str(event.name)
old = None
try:
	old = event.oldName
except:
	old = None
try:
	if old and str(old) != name:
		resp = system.user.editRole('default', str(old), name)
		action = 'renamed "' + str(old) + '" -> "' + name + '"'
	else:
		resp = system.user.addRole('default', name)
		action = 'added "' + name + '"'
	errs = [str(x) for x in resp.getErrors()]
	if errs:
		self.view.custom.lastEvent = 'onRoleSave ERRORS: ' + '; '.join(errs)
	else:
		self.view.custom.lastEvent = 'onRoleSave ' + action
except:
	self.view.custom.lastEvent = 'onRoleSave FAILED: ' + str(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

